/* 4-Color Cohesive Palette:
   --c-bg: #2b1d2f (Dark plum background)
   --c-surface: #4a344d (Muted purple-brown card)
   --c-light: #f6ecd2 (Warm ivory text & highlights)
   --c-accent: #88c070 (Sage green accent)
*/

:root {
  --c-bg: #2b1d2f;
  --c-surface: #4a344d;
  --c-card-border: #1a0f1d;
  --c-light: #f6ecd2;
  --c-accent: #88c070;
  --c-accent-dark: #5c8b47;
  --c-alert: #e06c75;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  background-color: var(--c-bg);
  color: var(--c-light);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.app-container {
  width: 100%;
  max-width: 440px;
}

.card {
  background-color: var(--c-surface);
  border: 4px solid var(--c-card-border);
  box-shadow:
    8px 8px 0 var(--c-card-border),
    inset 4px 4px 0 rgba(246, 236, 210, 0.15);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  text-align: center;
}

.card-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.pixel-title {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--c-light);
  text-shadow: 2px 2px 0 var(--c-card-border);
}

.subtitle {
  font-size: 1rem;
  color: var(--c-accent);
  letter-spacing: 1px;
}

.art-frame {
  display: flex;
  justify-content: center;
  align-items: center;
  background: var(--c-bg);
  border: 4px solid var(--c-card-border);
  padding: 12px;
  box-shadow: inset 4px 4px 0 rgba(0, 0, 0, 0.4);
}

#tea-canvas {
  display: block;
  width: 128px;
  height: 128px;
  image-rendering: pixelated;
}

.preset-group {
  border: none;
  padding: 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.tea-options {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.pixel-btn {
  appearance: none;
  border: 3px solid var(--c-card-border);
  background-color: var(--c-bg);
  color: var(--c-light);
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 10px 8px;
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--c-card-border);
  transition: transform 0.05s ease, background-color 0.1s ease;
  outline-offset: 2px;
}

.pixel-btn:hover:not(:disabled) {
  background-color: var(--c-accent-dark);
  color: #ffffff;
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--c-light);
}

.pixel-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--c-card-border);
}

.pixel-btn.active {
  background-color: var(--c-accent);
  color: var(--c-card-border);
  border-color: var(--c-light);
  box-shadow: inset 2px 2px 0 rgba(0, 0, 0, 0.2);
}

.pixel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

.timer-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  min-height: 84px;
  justify-content: center;
}

.timer-display {
  font-size: 2.8rem;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--c-light);
  background: var(--c-card-border);
  padding: 8px 24px;
  border: 3px solid var(--c-accent);
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.3);
}

.ready-banner {
  font-size: 1.15rem;
  font-weight: bold;
  color: var(--c-light);
  background-color: var(--c-accent-dark);
  padding: 6px 12px;
  border: 2px solid var(--c-light);
  letter-spacing: 1px;
  animation: pixel-pulse 0.8s steps(2, start) infinite;
}

@keyframes pixel-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.controls .pixel-btn {
  flex: 1;
  font-size: 1.1rem;
  padding: 12px;
}

.primary-btn {
  background-color: var(--c-accent);
  color: var(--c-card-border);
}

.primary-btn:hover:not(:disabled) {
  background-color: #9cd484;
  color: var(--c-card-border);
}

.secondary-btn {
  background-color: #6d4b73;
  color: var(--c-light);
}

.secondary-btn:hover:not(:disabled) {
  background-color: var(--c-alert);
  color: var(--c-light);
}

@media (max-width: 380px) {
  .tea-options {
    grid-template-columns: 1fr;
  }
  .timer-display {
    font-size: 2.2rem;
    padding: 6px 16px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let timerInterval = null;
  let selectedTime = 120;
  let remainingTime = 120;
  let isRunning = false;
  let steamTick = 0;
  let steamInterval = null;

  const timerDisplay = document.getElementById('timer-display');
  const readyMessage = document.getElementById('ready-message');
  const startBtn = document.getElementById('start-btn');
  const cancelBtn = document.getElementById('cancel-btn');
  const presetButtons = document.querySelectorAll('.tea-btn');
  const canvas = document.getElementById('tea-canvas');
  const ctx = canvas.getContext('2d');

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    const paddedSeconds = seconds < 10 ? '0' + seconds : seconds;
    return `${minutes}:${paddedSeconds}`;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingTime);
  }

  function drawPixelArt() {
    const size = 16;
    const scale = canvas.width / size; // 128 / 16 = 8

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const colorDark = '#1a0f1d';
    const colorCup = '#f6ecd2';
    const colorTea = '#88c070';
    const colorSteam = 'rgba(246, 236, 210, 0.7)';

    function drawPixel(x, y, color) {
      ctx.fillStyle = color;
      ctx.fillRect(x * scale, y * scale, scale, scale);
    }

    // Steam when running or completed
    if (isRunning || !readyMessage.hasAttribute('hidden')) {
      const offset = steamTick % 4;
      const steamPixels = [
        { x: 5, y: 3 - (offset % 2) },
        { x: 6, y: 2 - Math.floor(offset / 2) },
        { x: 8, y: 3 - ((offset + 1) % 2) },
        { x: 9, y: 2 - Math.floor((offset + 1) / 2) },
        { x: 11, y: 3 - ((offset + 2) % 2) },
        { x: 10, y: 2 - Math.floor((offset + 2) / 2) }
      ];
      steamPixels.forEach(p => {
        if (p.y >= 0 && p.y < 5) {
          drawPixel(p.x, p.y, colorSteam);
        }
      });
    }

    // Cup Rim
    for (let x = 4; x <= 11; x++) {
      drawPixel(x, 5, colorDark);
    }

    // Cup Interior & Liquid
    for (let y = 6; y <= 11; y++) {
      const xStart = y === 11 ? 5 : 4;
      const xEnd = y === 11 ? 10 : 11;
      for (let x = xStart; x <= xEnd; x++) {
        if (x === xStart || x === xEnd || y === 11) {
          drawPixel(x, y, colorCup);
        } else {
          drawPixel(x, y, colorTea);
        }
      }
    }

    // Saucer Base
    for (let x = 3; x <= 12; x++) {
      drawPixel(x, 12, colorDark);
      drawPixel(x, 13, colorCup);
    }

    // Cup Handle
    drawPixel(12, 7, colorCup);
    drawPixel(13, 7, colorCup);
    drawPixel(13, 8, colorCup);
    drawPixel(13, 9, colorCup);
    drawPixel(12, 9, colorCup);
  }

  function stopSteamAnimation() {
    if (steamInterval) {
      clearInterval(steamInterval);
      steamInterval = null;
    }
    steamTick = 0;
  }

  function startSteamAnimation() {
    stopSteamAnimation();
    steamInterval = setInterval(() => {
      steamTick++;
      drawPixelArt();
    }, 250);
  }

  function handlePresetClick(e) {
    if (isRunning) return;

    const target = e.currentTarget;
    presetButtons.forEach(btn => {
      btn.classList.remove('active');
      btn.setAttribute('aria-pressed', 'false');
    });

    target.classList.add('active');
    target.setAttribute('aria-pressed', 'true');

    selectedTime = parseInt(target.getAttribute('data-time'), 10);
    remainingTime = selectedTime;
    readyMessage.setAttribute('hidden', '');
    updateDisplay();
    drawPixelArt();
  }

  function startTimer() {
    if (isRunning) return;

    isRunning = true;
    readyMessage.setAttribute('hidden', '');
    startBtn.disabled = true;
    presetButtons.forEach(btn => {
      btn.disabled = true;
    });

    startSteamAnimation();

    timerInterval = setInterval(() => {
      if (remainingTime > 0) {
        remainingTime--;
        updateDisplay();
      }

      if (remainingTime <= 0) {
        clearInterval(timerInterval);
        timerInterval = null;
        isRunning = false;
        startBtn.disabled = false;
        presetButtons.forEach(btn => {
          btn.disabled = false;
        });
        readyMessage.removeAttribute('hidden');
        drawPixelArt();
      }
    }, 1000);
  }

  function cancelTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    isRunning = false;
    remainingTime = selectedTime;
    startBtn.disabled = false;
    presetButtons.forEach(btn => {
      btn.disabled = false;
    });
    readyMessage.setAttribute('hidden', '');
    stopSteamAnimation();
    updateDisplay();
    drawPixelArt();
  }

  presetButtons.forEach(btn => {
    btn.addEventListener('click', handlePresetClick);
  });

  startBtn.addEventListener('click', startTimer);
  cancelBtn.addEventListener('click', cancelTimer);

  // Initial render
  updateDisplay();
  drawPixelArt();
});
